// Error The single error envelope every failure in this API uses.
type Error struct {
	Error struct {
		// Code Stable and never reused for a different meaning. Generated into both
		// clients as an enum, so a client can handle codes exhaustively and a new
		// one is a compile-time prompt rather than a runtime surprise.
		//
		// Messages are for humans and may be reworded at any time. Only the code
		// is machine logic.
		Code        ErrorCode    `json:"code"`
		FieldErrors []FieldError `json:"field_errors"`

		// Message Human readable, never machine logic.
		Message string `json:"message"`

		// RequestID Correlation identifier, also returned in X-Request-ID. It is
		// what makes a user's support report resolvable to one trace.
		//
		//
		// Examples: req_01a0301daa1070009
		RequestID string `json:"request_id"`

		// Retryable Whether retrying the same request could plausibly succeed.
		Retryable bool `json:"retryable"`
	} `json:"error"`
}

