// ServerInterface represents all server handlers.
type ServerInterface interface {
	// RequestTokenEmail Send a verification, recovery, sign-in or code email
	// (POST /auth/email/request)
	RequestTokenEmail(w http.ResponseWriter, r *http.Request)
	// ConfirmEmailVerification Confirm an email address with a verification token
	// (POST /auth/email/verify)
	ConfirmEmailVerification(w http.ResponseWriter, r *http.Request)
	// Login Exchange credentials for a session
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ConsumeMagicLink Sign in with a magic link token
	// (POST /auth/magic/consume)
	ConsumeMagicLink(w http.ResponseWriter, r *http.Request)
	// ListOAuthProviders Which sign-in providers this deployment offers
	// (GET /auth/oauth/providers)
	ListOAuthProviders(w http.ResponseWriter, r *http.Request)
	// CompleteOAuth Finish signing in with a provider
	// (POST /auth/oauth/{provider}/callback)
	CompleteOAuth(w http.ResponseWriter, r *http.Request, provider OAuthProvider)
	// StartOAuth Begin signing in with a provider
	// (POST /auth/oauth/{provider}/start)
	StartOAuth(w http.ResponseWriter, r *http.Request, provider OAuthProvider)
	// ConsumeOTP Sign in with a one-time code
	// (POST /auth/otp/consume)
	ConsumeOTP(w http.ResponseWriter, r *http.Request)
	// ConfirmPasswordReset Set a new password with a recovery token
	// (POST /auth/password/reset)
	ConfirmPasswordReset(w http.ResponseWriter, r *http.Request)
	// Refresh Rotate the session using a refresh token
	// (POST /auth/refresh)
	Refresh(w http.ResponseWriter, r *http.Request)
	// Register Register a candidate or an organisation
	// (POST /auth/register)
	Register(w http.ResponseWriter, r *http.Request, params RegisterParams)
	// ListDisciplines List the professions the product serves
	// (GET /catalog/disciplines)
	ListDisciplines(w http.ResponseWriter, r *http.Request)
	// ListInterviewShapes List interview shapes with their runnable lengths
	// (GET /catalog/interview-shapes)
	ListInterviewShapes(w http.ResponseWriter, r *http.Request)
	// ListPersonas List interviewer personas
	// (GET /catalog/personas)
	ListPersonas(w http.ResponseWriter, r *http.Request)
	// ListRoles List catalogued roles with their valid combinations
	// (GET /catalog/roles)
	ListRoles(w http.ResponseWriter, r *http.Request)
	// GetLiveness Report whether the process is running
	// (GET /healthz)
	GetLiveness(w http.ResponseWriter, r *http.Request)
	// GetInterviewBrief What the interviewer needs to run this session
	// (GET /internal/interviews/{sessionId}/brief)
	GetInterviewBrief(w http.ResponseWriter, r *http.Request, sessionID SessionID, params GetInterviewBriefParams)
	// IngestServiceEvents The agent writes conversation into the durable timeline
	// (POST /internal/interviews/{sessionId}/events)
	IngestServiceEvents(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// CreateInterview Create a practice interview from a catalogue selection
	// (POST /interviews)
	CreateInterview(w http.ResponseWriter, r *http.Request)
	// GetPracticeConsent The current practice recording consent text, versioned
	// (GET /interviews/practice-consent)
	GetPracticeConsent(w http.ResponseWriter, r *http.Request)
	// GetInterview One practice session, as its owner sees it
	// (GET /interviews/{sessionId})
	GetInterview(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// CompleteInterview Seal the transcript and hand the session to evaluation
	// (POST /interviews/{sessionId}/complete)
	CompleteInterview(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// GetDelivery The delivery analysis, measured and gated
	// (GET /interviews/{sessionId}/delivery)
	GetDelivery(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// RecordInsightFeedback Say whether a generated insight described you
	// (PUT /interviews/{sessionId}/delivery/feedback)
	RecordInsightFeedback(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// ReplayControlEvents Replay the durable timeline after a cursor
	// (GET /interviews/{sessionId}/events)
	ReplayControlEvents(w http.ResponseWriter, r *http.Request, sessionID SessionID, params ReplayControlEventsParams)
	// IngestControlEvents Send a batch of control events for the current epoch
	// (POST /interviews/{sessionId}/events)
	IngestControlEvents(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// GetResults The evaluation result, sufficiency and coverage included
	// (GET /interviews/{sessionId}/results)
	GetResults(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// GetReview The coaching review, derived and fact-preserving
	// (GET /interviews/{sessionId}/review)
	GetReview(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// StartInterview Start a ready session and receive the room grant
	// (POST /interviews/{sessionId}/start)
	StartInterview(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// GetTranscript The assembled transcript, provenance included
	// (GET /interviews/{sessionId}/transcript)
	GetTranscript(w http.ResponseWriter, r *http.Request, sessionID SessionID)
	// CreateRedo Retake one answer as a new, linked practice session
	// (POST /interviews/{sessionId}/turns/{turnId}/redos)
	CreateRedo(w http.ResponseWriter, r *http.Request, sessionID SessionID, turnID int)
	// GetCurrentUser Describe the authenticated user and their active tenant
	// (GET /me)
	GetCurrentUser(w http.ResponseWriter, r *http.Request)
	// SetActiveTenant Choose which workspace this session acts under
	// (PUT /me/active-tenant)
	SetActiveTenant(w http.ResponseWriter, r *http.Request)
	// GetDeliveryBaseline The caller's own delivery ranges, once there is enough history
	// (GET /me/delivery-baseline)
	GetDeliveryBaseline(w http.ResponseWriter, r *http.Request)
	// ListDocuments List the candidate's own documents, every version and state
	// (GET /me/documents)
	ListDocuments(w http.ResponseWriter, r *http.Request)
	// StartDocumentUpload Start a CV upload
	// (POST /me/documents)
	StartDocumentUpload(w http.ResponseWriter, r *http.Request)
	// DeleteDocument Delete a stored document
	// (DELETE /me/documents/{documentId})
	DeleteDocument(w http.ResponseWriter, r *http.Request, documentID DocumentID)
	// AbortDocumentUpload Abandon a stalled upload
	// (POST /me/documents/{documentId}/abort)
	AbortDocumentUpload(w http.ResponseWriter, r *http.Request, documentID DocumentID)
	// CompleteDocumentUpload Finalise an upload
	// (POST /me/documents/{documentId}/complete)
	CompleteDocumentUpload(w http.ResponseWriter, r *http.Request, documentID DocumentID)
	// ListDocumentFacts List what extraction read from one document
	// (GET /me/documents/{documentId}/facts)
	ListDocumentFacts(w http.ResponseWriter, r *http.Request, documentID DocumentID)
	// ReviewFact Confirm, correct or reject one extracted fact
	// (POST /me/facts/{factId}/review)
	ReviewFact(w http.ResponseWriter, r *http.Request, factID FactID)
	// ListMemberships List the workspaces this person belongs to
	// (GET /me/memberships)
	ListMemberships(w http.ResponseWriter, r *http.Request)
	// GetProfile Read the candidate's own profile
	// (GET /me/profile)
	GetProfile(w http.ResponseWriter, r *http.Request)
	// SaveProfile Replace the candidate's own profile
	// (PUT /me/profile)
	SaveProfile(w http.ResponseWriter, r *http.Request)
	// ListMySessions Every session the caller owns, every lifecycle state included
	// (GET /me/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// GetReadiness Report whether this process can serve traffic
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// ListMembers Everyone in the active workspace
	// (GET /tenant/members)
	ListMembers(w http.ResponseWriter, r *http.Request)
	// InviteMember Invite an existing account to the workspace
	// (POST /tenant/members)
	InviteMember(w http.ResponseWriter, r *http.Request)
	// RevokeMember Revoke a member's access
	// (DELETE /tenant/members/{membershipId})
	RevokeMember(w http.ResponseWriter, r *http.Request, membershipID MembershipID, params RevokeMemberParams)
	// ChangeMemberRole Move a member to another role
	// (PATCH /tenant/members/{membershipId})
	ChangeMemberRole(w http.ResponseWriter, r *http.Request, membershipID MembershipID)
	// GetTenantQuota The limit, what remains, and where the warning stands
	// (GET /tenant/quota)
	GetTenantQuota(w http.ResponseWriter, r *http.Request)
	// GetTenantUsage What the workspace has used, in the invoice's own terms
	// (GET /tenant/usage)
	GetTenantUsage(w http.ResponseWriter, r *http.Request)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// RequestTokenEmail operation middleware
func (siw *ServerInterfaceWrapper) RequestTokenEmail(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.RequestTokenEmail(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

// ConfirmEmailVerification operation middleware
func (siw *ServerInterfaceWrapper) ConfirmEmailVerification(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.ConfirmEmailVerification(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

// Login operation middleware
func (siw *ServerInterfaceWrapper) Login(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.Login(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

